package com.nigson.commerce.payment;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import com.nigson.commerce.order.*;
import com.nigson.shared.events.EventCodec;
/** Bounded owned polling. Crashes leave durable intents, receipts and UNKNOWN outcomes recoverable. */
public final class PaymentWorker {
 private final JdbcTemplate jdbc;private final OrderPolicy binding;private final PaymentPolicy policy;private final CheckoutPayments payments;private final RefundOperations refunds;private final PaymentReceiptProcessor receipts;private final PaymentExpiry expiry;private final Clock clock;private final int limit;
 public PaymentWorker(JdbcTemplate jdbc,OrderPolicy binding,PaymentPolicy policy,CheckoutPayments payments,RefundOperations refunds,PaymentReceiptProcessor receipts,PaymentExpiry expiry,Clock clock,int limit){if(limit<1||limit>100)throw new IllegalArgumentException("PAYMENT_WORKER_LIMIT_INVALID");this.jdbc=jdbc;this.binding=binding;this.policy=policy;this.payments=payments;this.refunds=refunds;this.receipts=receipts;this.expiry=expiry;this.clock=clock;this.limit=limit;}
 @Scheduled(fixedDelayString="${NIGSON_PAYMENT_WORKER_DELAY_MS:30000}",initialDelayString="${NIGSON_PAYMENT_WORKER_DELAY_MS:30000}")
 public void poll(){policy.require();var work=jdbc.queryForList("SELECT kind,id FROM (SELECT 1 AS kind,r.id,r.updated_at AS due FROM commerce.refund r JOIN commerce.payment_attempt a ON a.id=r.attempt_id WHERE a.provider='PAYSTACK' AND a.merchant_account=? AND a.provider_mode=? AND (r.state='APPROVED' OR r.state IN ('SUBMITTING','PENDING','UNKNOWN') AND r.updated_at<=?) UNION ALL SELECT 2 AS kind,id,updated_at AS due FROM commerce.webhook_receipt WHERE provider='PAYSTACK' AND merchant_account=? AND (state='RECEIVED' OR state='RETRY' AND updated_at<=?) UNION ALL SELECT 3 AS kind,order_id AS id,coalesce(next_reconcile_at,created_at) AS due FROM commerce.payment_attempt WHERE provider='PAYSTACK' AND merchant_account=? AND provider_mode=? AND state IN ('INITIATING','PENDING','UNKNOWN') AND (next_reconcile_at IS NULL OR next_reconcile_at<=?) UNION ALL SELECT 4 AS kind,o.id,o.reservation_expires_at AS due FROM commerce.sales_order o JOIN commerce.payment_attempt a ON a.order_id=o.id WHERE a.provider='PAYSTACK' AND a.merchant_account=? AND a.provider_mode=? AND o.status='PENDING' AND o.reservation_expires_at<=?) work ORDER BY due,kind,id LIMIT ?",binding.merchantAccount(),binding.mode(),java.sql.Timestamp.from(clock.instant().minusSeconds(30)),binding.merchantAccount(),java.sql.Timestamp.from(clock.instant().minusSeconds(30)),binding.merchantAccount(),binding.mode(),java.sql.Timestamp.from(clock.instant()),binding.merchantAccount(),binding.mode(),java.sql.Timestamp.from(clock.instant()),limit);
  long deadline=System.nanoTime()+Duration.ofSeconds(20).toNanos();for(var item:work){if(System.nanoTime()>=deadline)return;UUID id=(UUID)item.get("id"),correlation=EventCodec.uuid7(clock.instant());int kind=((Number)item.get("kind")).intValue();try{switch(kind){case 1->{refunds.submit(id,correlation);refunds.inspect(id,correlation);}case 2->receipts.process(id,correlation);case 3->payments.inspect(id,correlation);case 4->expiry.expire(id,correlation);default->throw new IllegalStateException("PAYMENT_WORK_KIND_INVALID");}}catch(RuntimeException failure){org.slf4j.LoggerFactory.getLogger(PaymentWorker.class).warn("PAYMENT_WORK_RETRY_REQUIRED");}}
 }
}
